/**
 * `@amc/kernel` — TypeScript twin of the N1–N4 governance kernel in
 * `services/langgraph/agency/kernel/` (Python is the reference).
 *
 * `tests/fixtures/kernel-parity.json` is generated by
 * `services/langgraph/tests/test_kernel_parity_fixture.py`, and every entry —
 * results and raised errors alike — must be reproduced here.
 *
 * Deliberate differences from Python, each failing closed rather than guessing:
 * - Function names are camelCase; record fields keep Python's snake_case so
 *   serialized shapes are identical.
 * - Python accepts enum members or their string values; the twin takes strings.
 * - Integral JS numbers are ints. A Python float with an integral value must be
 *   a `PyFloat`; an unsafe integer must be a `bigint` (refused otherwise).
 * - `content_fingerprint` uses `default=str` for unknown objects in Python;
 *   the twin refuses anything outside `PyJsonValue`.
 * - `ArtifactRegistry.commit` checks `status` (Python stores an unchecked
 *   value and fails later in `serialize`). `deserializeVersion` refuses
 *   wrongly-typed fields Python would store unconverted.
 * - Python's `TransitionContext` is a dataclass with defaults; here every
 *   field is optional and an absent one takes the same fail-closed default.
 */
export * from './errors';
export * from './models';
export * from './ontology';
export * from './lifecycle';
export * from './roles';
export * from './registry';
export { PyFloat, compareCodePoints, floatRepr, pyRepr, pySorted, pyStr } from './pyformat';
export { pyJsonDumps, type PyJsonValue } from './pyjson';
export { sha256Hex } from './sha256';
